120	    private ProcessResult runCommand(String... command) {
121	        try {
122	            ProcessBuilder pb = new ProcessBuilder(command);
123	            pb.redirectErrorStream(true);
124	            Process process = pb.start();
125	            StringBuilder output = new StringBuilder();
