129	                    output.append(line).append("\n");
130	                }
131	            }
132	            int exitCode = process.waitFor();
133	            return new ProcessResult(output.toString().trim(), exitCode);
134	        } catch (Exception e) {
135	            String message = e.getMessage() != null ? e.getMessage() : "Command execution failed";
136	            return new ProcessResult(message, -1);
137	        }
138	    }
